// Main computational kernel: Floyd–Warshall
// Original C loops:
//
// for (k = 0; k < _PB_N; k++)
//   for (i = 0; i < _PB_N; i++)
//     for (j = 0; j < _PB_N; j++)
//       path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
//                      path[i][j] : path[i][k] + path[k][j];
//
// Optimized Noarr version below keeps the same semantics but
// improves locality and reduces redundant memory accesses:
//   - k stays outer and sequential (DP order preserved).
//   - For each k we snapshot row k (path[k][j]) into a temporary
//     1D buffer `row` (size O(N)).
//   - For each (k,i) we hoist path[i][k] into a scalar `pik` and
//     reuse it across all j for that row.
//
// Because all edge weights are non‑negative in this benchmark,
// path[i][k] and path[k][j] are never improved during stage k;
// thus it is semantically safe to read them once per stage k
// (for row) / once per (k,i) (for pik) and reuse them.
//
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

	// Temporary buffer for the k‑th row: row[j] = path[k][j]
	// Layout: 'j' is the only (and inner) dimension, so accesses are contiguous.
	auto row = noarr::bag(noarr::scalar<num_t>() ^ j_vec ^ noarr::set_length<'j'>(n));
	auto row_ref = row.get_ref();

#pragma scop
	// Outer loop: k = 0 .. n-1  (must remain sequential)
	traverser(k_struct).for_each([&](auto sk) {
		const std::size_t k = get_index<'k'>(sk);

		// ------------------------------------------------------------------
		// 1) Snapshot row k of 'path' into the temporary buffer `row_ref`
		//    so that all updates for this k use the same row values.
		//
		//    This corresponds to taking d^{(k-1)}[k, j] for all j.
		//    Because of non‑negative weights, the original in‑place
		//    triple loop never improves path[k][j] during stage k, so
		//    reading it once here is equivalent.
		// ------------------------------------------------------------------

		// View of path with i fixed to k: a 1D structure over 'j'
		auto path_row_k = path ^ noarr::fix<'i'>(k);

		// Copy row k: row_ref[j] = path[k][j] for all j
		traverser(row_ref, path_row_k).for_each([&](auto sj) {
			row_ref[sj] = path_row_k[sj];
		});

		// ------------------------------------------------------------------
		// 2) For this fixed k, relax all pairs (i, j):
		//
		//        path[i][j] = min(path[i][j], path[i][k] + row_ref[j])
		//
		//    We hoist path[i][k] into a scalar `pik` once per (k,i) to
		//    avoid reloading it for every j.
		//    Accesses to path[i][j] and row_ref[j] are contiguous in j.
		// ------------------------------------------------------------------

		// Outer loop over rows i
		traverser(path).template for_dims<'i'>([&](auto trav_i) {
			// trav_i has 'i' fixed, 'j' remaining
			auto si = trav_i.state(); // state with just 'i'

			// path[i][k] is invariant over j for this (k, i)
			const num_t pik = path[si + noarr::idx<'j'>(k)];

			// Inner loop over columns j
			trav_i.template for_each<'j'>([&](auto sij) {
				const std::size_t j = get_index<'j'>(sij);

				// candidate path via intermediate vertex k
				const num_t via_k = pik + row_ref[noarr::idx<'j'>(j)];

				num_t &pij = path[sij];
				pij = (pij < via_k) ? pij : via_k;
			});
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// build common length descriptor
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data
	auto path = noarr::bag(noarr::scalar<num_t>() ^ tuning.path_layout ^ set_lengths);

	// initialize data
	init_array(path.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_floyd_warshall(n, path.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (for DCE / correctness checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, path.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
