// Optimized Floyd–Warshall kernel.
//
// Original algorithm:
//
//   for (k = 0; k < N; k++)
//     for (i = 0; i < N; i++)
//       for (j = 0; j < N; j++)
//         path[i][j] = min(path[i][j], path[i][k] + path[k][j]);
//
// This implementation applies the following optimizations, while preserving
// the original semantics:
//
// 1) Keep the outer loop over k sequential (DP over k).
//
// 2) For each k, snapshot:
//      - column k: col[i] = path[i][k]
//      - row    k: row[j] = path[k][j]
//    into temporary 1D buffers (O(N) memory each). These are read‑only inside
//    the update phase. This precisely matches the mathematical recurrence
//    d^{(k)}[i,j] = min(d^{(k-1)}[i,j], d^{(k-1)}[i,k] + d^{(k-1)}[k,j])
//    and removes any read‑after‑write hazards when reordering (i,j).
//
// 3) Inside each fixed k, perform a blocked traversal of the (i,j) space
//    using noarr::into_blocks_dynamic to improve cache locality. We tile
//    both row ('i') and column ('j') dimensions but keep the data layout
//    itself unchanged (still row-major with 'j' contiguous).
//
// 4) For each fixed (k, i) within a tile, hoist col[i] into a scalar
//    register (pik) reused across the inner j-loop.
//
// All loops over indices are expressed using noarr::traverser and
// its for_each / for_dims methods, as required.
//
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// 1D helper structure to iterate k in [0, n)
	auto k_struct = scalar<char>() ^ k_vec ^ set_length<'k'>(n);

	// Temporary buffers:
	//   col[i] = path[i][k]
	//   row[j] = path[k][j]
	// Each has O(N) elements, negligible vs. O(N^2) elements in 'path'.
	auto col_bag = noarr::bag(scalar<num_t>() ^ i_vec ^ set_length<'i'>(n));
	auto row_bag = noarr::bag(scalar<num_t>() ^ j_vec ^ set_length<'j'>(n));

	// Reference bags are copyable and cheap to capture in lambdas
	auto col = col_bag.get_ref();
	auto row = row_bag.get_ref();

	// Tiling factors for i (rows) and j (columns).
	// These are compile‑time constants but passed as runtime values to
	// into_blocks_dynamic so that remainder tiles are handled correctly.
	constexpr std::size_t tile_i = 32;
	constexpr std::size_t tile_j = 32;

	// Proto-structure that splits 'i' and 'j' into tiles:
	//   'i' -> ('I', 'i') with guard dim 's'
	//   'j' -> ('J', 'j') with guard dim 't'
	//
	// The layout of 'path' is not changed; only the traversal order is.
	auto block_order =
		into_blocks_dynamic<'i', 'I', 'i', 's'>(tile_i) ^
		into_blocks_dynamic<'j', 'J', 'j', 't'>(tile_j);

#pragma scop
	// Outer DP loop over k must remain sequential.
	traverser(k_struct).for_each([=](auto sk) {
		auto k = get_index<'k'>(sk);

		// -----------------------------------------------------------------
		// Snapshot column k and row k of 'path' at the beginning of this
		// k-iteration: col[i] = path[i][k], row[j] = path[k][j].
		// -----------------------------------------------------------------

		// col[i] = path[i][k]
		traverser(col).for_each([=](auto si) {
			// si contains index 'i'
			// Extend si with j = k to index path[i][k]
			auto sik = si.template with<index_in<'j'>>(k);
			col[si] = path[sik];
		});

		// row[j] = path[k][j]
		traverser(row).for_each([=](auto sj) {
			// sj contains index 'j'
			// Extend sj with i = k to index path[k][j]
			auto skj = sj.template with<index_in<'i'>>(k);
			row[sj] = path[skj];
		});

		// -----------------------------------------------------------------
		// Blocked relaxation phase for fixed k:
		//   for tiles (I,J)
		//     for rows i in tile I
		//       pik = col[i]
		//       for columns j in tile J
		//         path[i,j] = min(path[i,j], pik + row[j])
		//
		// Traverser(order(block_order)) drives the tile structure, while
		// the states handed to the lambdas always carry the original
		// indices 'i' and 'j', so they can be used directly with 'path',
		// 'col', and 'row'.
		// -----------------------------------------------------------------
		traverser(path).order(block_order)
			// Outer tile loops over 'I' (row tiles) and 'J' (column tiles)
			.template for_dims<'I', 'J'>([=](auto tile_trav) {
				// Iterate rows 'i' inside this tile; 's' is the guard dimension
				// created by into_blocks_dynamic for 'i' (used internally to
				// skip out-of-range rows in the last tile).
				tile_trav.template for_dims<'i', 's'>([=](auto row_trav) {
					// State with current row index 'i' (original coordinates)
					auto s_row = row_trav.state();

					// Hoist col[i] for this (k, i) into a scalar register.
					// 'col' ignores any superfluous indices in s_row, it only
					// uses 'i'.
					num_t pik = col[s_row];

					// Now traverse all valid 'j' in this tile for the fixed 'i'.
					// for_each will internally iterate 'j' and its guard 't'.
					row_trav.for_each([=](auto s_ij) {
						// s_ij contains original indices 'i' and 'j'.
						// 'row' ignores 'i' and uses only 'j'.
						num_t via_k = pik + row[s_ij];

						// Update path[i,j] if the path via k is shorter.
						num_t &pij = path[s_ij];
						if (via_k < pij)
							pij = via_k;
					});
				});
			});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// build common length descriptor
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data
	auto path = noarr::bag(noarr::scalar<num_t>() ^ tuning.path_layout ^ set_lengths);

