	// Both are O(N) each, which is negligible compared to the O(N^2)
	// storage of 'path' and improves cache behavior and load redundancy.
	auto col = noarr::bag(noarr::scalar<num_t>() ^ i_vec ^ noarr::set_length<'i'>(n));
	auto row = noarr::bag(noarr::scalar<num_t>() ^ j_vec ^ noarr::set_length<'j'>(n));

#pragma scop
	// Outer loop: k = 0 .. n-1 (must remain sequential)
	traverser(k_struct).for_each([&](auto sk) {
		auto k = get_index<'k'>(sk);

		// -----------------------------------------------------------------
		// Snapshot the k-th column and k-th row of 'path'
		// -----------------------------------------------------------------
		// col[i] = path[i][k]
		traverser(col).for_each([&](auto si) {
			auto i = get_index<'i'>(si);
			col[si] = path[noarr::idx<'i', 'j'>(i, k)];
		});

		// row[j] = path[k][j]
		traverser(row).for_each([&](auto sj) {
			auto j = get_index<'j'>(sj);
			row[sj] = path[noarr::idx<'i', 'j'>(k, j)];
		});

		// -----------------------------------------------------------------
		// Relax all pairs (i, j) via intermediate vertex k
		//
		// We express the (i, j) nest as:
		//   for i:
		//     pik = col[i];          // hoisted out of inner j-loop
		//     for j:
		//       via_k = pik + row[j]
		//       path[i][j] = min(path[i][j], via_k)
		//
		// Using for_dims<'i'> gives us a per-row traverser with 'i' fixed;
		// trav_i.for_each then iterates all j for that fixed i.
		// -----------------------------------------------------------------
		traverser(path).template for_dims<'i'>([&](auto trav_i) {
			// trav_i has 'i' fixed; obtain its state to get the row index
			auto state_i = trav_i.state();
			auto i = get_index<'i'>(state_i);

			// d^{k-1}[i, k] (stored in 'col') is reused for all j
			num_t pik = col[noarr::idx<'i'>(i)];

			// Inner loop over all columns j for this fixed (k, i)
			trav_i.for_each([&](auto sij) {
				auto j = get_index<'j'>(sij);

				// Candidate distance via intermediate vertex k
				num_t via_k = pik + row[noarr::idx<'j'>(j)];

				num_t &pij = path[sij];
				if (via_k < pij)
					pij = via_k;
			});
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// build common length descriptor
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data
	auto path = noarr::bag(noarr::scalar<num_t>() ^ tuning.path_layout ^ set_lengths);

	// initialize data
	init_array(path.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_floyd_warshall(n, path.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (for DCE / correctness checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, path.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
